  { isLattice = Sub-isLattice
  ; minimum = record { infimum = 0ˢ ; greatest = λ {G} →
    λ {G} {f} {a} {i} → lift (⊥ {f a i})
    }
  ; maximum = record { supremum = 1ˢ ; greatest = λ {G} →
    λ {f a} → lift tt
    }
  }
  where open IsBoundedLattice _≈_ _≤_ _∨_ _∧_

